   129→    FROM signal_reports sr
   130→    JOIN repeaters r ON r.id = sr.repeater_id
   131→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0 AND sr.readability IS NOT NULL
   132→    GROUP BY sr.repeater_id
   133→    ORDER BY r.sort_order
   134→  `).all(eid) as any[];
   135→
   136→  const bezirkStats = db.prepare(`
   137→    SELECT bl.name as bundesland, bl.code as bundesland_code, bl.sort_order as bl_sort,
   138→      bz.code as bezirk_code, bz.name as bezirk_name, bz.is_capital,
   139→      COUNT(DISTINCT sr.operator_id) as participants,
   140→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
   141→    FROM signal_reports sr
   142→    JOIN bezirke bz ON bz.code = sr.bezirk_code
   143→    JOIN bundeslaender bl ON bl.code = bz.bundesland_code
   144→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   145→    GROUP BY bz.code
   146→    ORDER BY bl.sort_order, bz.code
   147→  `).all(eid) as any[];
   148→
   149→  const blStats = db.prepare(`
   150→    SELECT
   151→      COALESCE(bl.name, 'Sonstige') as bundesland,
   152→      o.bundesland_code,
   153→      COUNT(DISTINCT sr.operator_id) as participants,
   154→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as reports
   155→    FROM signal_reports sr
   156→    JOIN operators o ON o.id = sr.operator_id
   157→    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
   158→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   159→    GROUP BY o.bundesland_code
   160→    ORDER BY o.bundesland_code
   161→  `).all(eid) as any[];
   162→
   163→  const participants = db.prepare(`
   164→    SELECT o.callsign, o.name, o.bezirk_code, o.bundesland_code, o.home_repeater,
   165→      bl.name as bundesland_name,
   166→      COUNT(CASE WHEN sr.readability IS NOT NULL THEN 1 END) as report_count,
   167→      GROUP_CONCAT(DISTINCT sr.suffix) as suffixes
   168→    FROM signal_reports sr
   169→    JOIN operators o ON o.id = sr.operator_id
   170→    LEFT JOIN bundeslaender bl ON bl.code = o.bundesland_code
   171→    WHERE sr.exercise_id = ? AND sr.is_op_marker = 0
   172→    GROUP BY sr.operator_id
   173→    ORDER BY bl.sort_order, o.bezirk_code, o.callsign
   174→  `).all(eid) as any[];
   175→
   176→  const stats = { totalParticipants, totalReports, perRepeater, bezirkStats, blStats, participants };
