   213→              : stats.blStats.map(bl => ({ label: `OE${parseInt(bl.bundesland_code, 10)}`, participants: bl.participants, reports: bl.reports }));
   214→            const chartLevel = stats.bezirkStats.length > 0 ? 'Bezirk' : 'Bundesland';
   215→
